do $$declare s text;begin s:=pg_get_functiondef('prospecting.personalization_api(text,jsonb)'::regprocedure);s:=replace(s,$x$elsif a='retry' then$x$,$x$elsif a='recover' then update prospecting.personalization_jobs set status=case when attempts<3 then 'queued' else 'failed' end,lease=null,lease_until=null,error='Expired worker lease recovered; unknown spend remains reserved' where status='running' and lease_until<now();get diagnostics n=row_count;return jsonb_build_object('recovered',n); elsif a='retry' then$x$);execute s;end$$;
